function TreeNode(left, right) {
    this.left = left;
    this.right = right;
}

function bottomUpTree(depth) {
    return depth > 0
        ? new TreeNode(bottomUpTree(depth - 1), bottomUpTree(depth - 1))
        : new TreeNode(null, null);
}

function itemCheck(node) {
    if (node.left === null) {
        return 1;
    }
    return 1 + itemCheck(node.left) + itemCheck(node.right);
}

function main() {
    const n = parseInt(process.argv[2], 10);
    const stretchDepth = n + 1;

    let stretchTree = bottomUpTree(stretchDepth);
    console.log(`stretch tree of depth ${stretchDepth}\t check: ${itemCheck(stretchTree)}`);
    stretchTree = null;

    const longLivedTree = bottomUpTree(n);

    for (let depth = 4; depth <= n; depth += 2) {
        const iterations = 1 << (n - depth + 4);
        let check = 0;
        for (let i = 0; i < iterations; i++) {
            check += itemCheck(bottomUpTree(depth));
        }
        console.log(`${iterations}\t trees of depth ${depth}\t check: ${check}`);
    }

    console.log(`long lived tree of depth ${n}\t check: ${itemCheck(longLivedTree)}`);
}

main();
