function fannkuch(n) {
  if (n <= 1) return [0, 0];
  if (n === 2) return [-1, 1];

  const p = new Int32Array(n);
  const q = new Int32Array(n);
  const s = new Int32Array(n);

  for (let i = 0; i < n; i++) {
    p[i] = i;
    q[i] = i;
    s[i] = i;
  }

  let sign = 1;
  let maxflips = 0;
  let sum = 0;
  const m = n - 1;

  while (true) {
    let q0 = p[0];
    if (q0 !== 0) {
      for (let i = 1; i < n; i++) q[i] = p[i];
      let flips = 1;
      while (true) {
        const qq = q[q0];
        if (qq === 0) {
          sum += sign * flips;
          if (flips > maxflips) maxflips = flips;
          break;
        }
        q[q0] = q0;
        if (q0 >= 3) {
          let i = 1, j = q0 - 1;
          while (i < j) {
            const t = q[i];
            q[i] = q[j];
            q[j] = t;
            i++;
            j--;
          }
        }
        q0 = qq;
        flips++;
      }
    }

    if (sign === 1) {
      const t = p[1];
      p[1] = p[0];
      p[0] = t;
      sign = -1;
    } else {
      const t = p[1];
      p[1] = p[2];
      p[2] = t;
      sign = 1;

      for (let i = 2; i < n; i++) {
        const sx = s[i];
        if (sx !== 0) {
          s[i] = sx - 1;
          break;
        }
        if (i === m) return [sum, maxflips];
        s[i] = i;
        const first = p[0];
        for (let j = 0; j <= i; j++) {
          p[j] = p[j + 1];
        }
        p[i + 1] = first;
      }
    }
  }
}

const n = parseInt(process.argv[2], 10);
const [checksum, maxFlips] = fannkuch(n);
console.log(`${checksum}\nPfannkuchen(${n}) = ${maxFlips}`);
