    const buffer = fs.readFileSync(0);
    if (!buffer || buffer.length === 0) return;

    // Locate the sequence labelled >THREE
    const target = Buffer.from('>THREE');
    let startIndex = buffer.indexOf(target);
    if (startIndex === -1) {
        startIndex = buffer.indexOf(Buffer.from('>three'));
        if (startIndex === -1) return;
    }

    // Skip the header line
    let lineEnd = buffer.indexOf(10, startIndex);
    if (lineEnd === -1) lineEnd = buffer.length;
    startIndex = lineEnd + 1;

    // Find end of sequence (next '>' at start of line or EOF)
    let endIndex = buffer.length;
    let nextHeader = buffer.indexOf(62, startIndex);
    while (nextHeader !== -1) {
        if (nextHeader === startIndex || buffer[nextHeader - 1] === 10) {
            endIndex = nextHeader;
            break;
        }
        nextHeader = buffer.indexOf(62, nextHeader + 1);
    }

    // Extract DNA sequence, ignoring newlines and converting to upper case
    const rawLen = endIndex - startIndex;
    const seq = new Uint8Array(rawLen);
    let len = 0;
    for (let i = startIndex; i < endIndex; i++) {
        const b = buffer[i];
        if (b !== 10 && b !== 13) {
            seq[len++] = (b >= 97 && b <= 122) ? (b - 32) : b;
        }
    }
    const cleanSeq = seq.subarray(0, len);

    // Count 1-mers and 2-mers
    const count1 = new Int32Array(256);
    const count2 = new Int32Array(65536);

    if (len > 0) {
        let prev = cleanSeq[0];
        count1[prev]++;
        for (let i = 1; i < len; i++) {
            const cur = cleanSeq[i];
            count1[cur]++;
            count2[(prev << 8) | cur]++;
            prev = cur;
        }
    }

    // 1-mer frequencies
    const res1 = [];
    for (let c = 0; c < 256; c++) {
        if (count1[c] > 0) {
            res1.push({
                key: String.fromCharCode(c),
                count: count1[c],
                pct: len > 0 ? (count1[c] * 100) / len : 0
            });
        }
    }
    res1.sort((a, b) => b.count - a.count || (a.key < b.key ? -1 : (a.key > b.key ? 1 : 0)));
