    const total2 = len - 1;
    for (let c = 0; c < 65536; c++) {
        if (count2[c] > 0) {
            const k = String.fromCharCode(c >> 8, c & 0xFF);
            res2.push({
                key: k,
                count: count2[c],
                pct: total2 > 0 ? (count2[c] * 100) / total2 : 0
            });
