function main() {
    const N = parseInt(process.argv[2], 10);
    if (isNaN(N) || N <= 0) return;

    let q = 1n;
    let r = 0n;
    let t = 1n;
    let k = 1n;
    let count = 0;
    let line = '';

    while (count < N) {
        // Compute integer division: (q * 3 + r) / t and (q * 4 + r) / t
        // If (q * 3 + r) / t == (q * 4 + r) / t, we can safely extract that digit.
        // Or equivalently using the standard Gibbons formulation:
        const n3 = 3n * q + r;
        const d1 = n3 / t;
        const n4 = n3 + q;
        const d2 = n4 / t;

        if (d1 === d2) {
            line += d1.toString();
            count++;

            if (count % 10 === 0) {
                process.stdout.write(`${line}\t:${count}\n`);
                line = '';
            }

            // Extract digit: compose with [10, -10*d; 0, 1]
            r = 10n * (r - d1 * t);
            q = 10n * q;
        } else {
            // Ingest next term: compose with [k, 4k+2; 0, 2k+1]
            const k2 = 2n * k + 1n;
            r = (2n * q + r) * k2;
            t = t * k2;
            q = q * k;
            k++;
        }
    }

    if (line.length > 0) {
        process.stdout.write(`${line.padEnd(10, ' ')}\t:${count}\n`);
    }
}

