  ['A', 'T'], ['C', 'G'], ['G', 'C'], ['T', 'A'], ['U', 'A'],
  ['M', 'K'], ['R', 'Y'], ['W', 'W'], ['S', 'S'], ['Y', 'R'],
  ['K', 'M'], ['V', 'B'], ['H', 'D'], ['D', 'H'], ['B', 'V'],
  ['N', 'N']
];

for (const [from, to] of pairs) {
  tbl[from.charCodeAt(0)] = to.charCodeAt(0);
  tbl[from.toLowerCase().charCodeAt(0)] = to.charCodeAt(0);
}

function writeAllSync(fd, buf, offset, length) {
  while (length > 0) {
    const written = fs.writeSync(fd, buf, offset, length);
    offset += written;
    length -= written;
  }
}

function main() {
  let inputBuf;
  try {
    inputBuf = fs.readFileSync(0);
  } catch (e) {
    return;
  }

  if (!inputBuf || inputBuf.length === 0) {
    return;
  }

  let outBuf = null;
  let pos = 0;

  while (pos < inputBuf.length) {
    pos = inputBuf.indexOf(62, pos); // '>'
    if (pos === -1) break;

    const headerStart = pos;
    let headerEnd = inputBuf.indexOf(10, pos); // '\n'
    if (headerEnd === -1) {
      headerEnd = inputBuf.length - 1;
    }

    writeAllSync(1, inputBuf, headerStart, headerEnd - headerStart + 1);

    const seqStart = headerEnd + 1;
    const nextHeader = inputBuf.indexOf(62, seqStart);
    const seqEnd = nextHeader === -1 ? inputBuf.length : nextHeader;

    const maxLen = Math.ceil((seqEnd - seqStart) * 61 / 60) + 1024;
    if (!outBuf || outBuf.length < maxLen) {
      outBuf = Buffer.allocUnsafe(maxLen);
    }

    let col = 0;
    let outPos = 0;

    for (let j = seqEnd - 1; j >= seqStart; j--) {
      const c = tbl[inputBuf[j]];
      if (c !== 0) {
        outBuf[outPos++] = c;
        if (++col === 60) {
          outBuf[outPos++] = 10;
          col = 0;
        }
      }
    }

    if (col > 0) {
      outBuf[outPos++] = 10;
    }

    if (outPos > 0) {
      writeAllSync(1, outBuf, 0, outPos);
    }

    pos = seqEnd;
  }
}

