function multiplyAv(n, v, out) {
  for (let i = 0; i < n; ++i) {
    let sum = 0.0;
    const i1 = i + 1;
    for (let j = 0; j < n; ++j) {
      const s = i + j;
      sum += v[j] / (((s * (s + 1)) >>> 1) + i1);
    }
    out[i] = sum;
  }
}

function multiplyAtv(n, v, out) {
  for (let i = 0; i < n; ++i) {
    let sum = 0.0;
    for (let j = 0; j < n; ++j) {
      const s = i + j;
      sum += v[j] / (((s * (s + 1)) >>> 1) + j + 1);
    }
    out[i] = sum;
  }
}

function multiplyAtAv(n, v, out, tmp) {
  multiplyAv(n, v, tmp);
  multiplyAtv(n, tmp, out);
}

function main() {
